import type { PluginModule, PluginInput, Hooks } from "@opencode-ai/plugin"
import * as core from "./core"

export const SelfImprovementPlugin: PluginModule = {
  id: "self-improvement",
  async server(input: PluginInput): Promise<Hooks> {
    // Initialize plugin state
    const eventBus = new core.EventBus()
    const journal = new core.Journal(input.directory)
    const storage = new core.Storage(input.directory)

    return {
      async dispose() {
        await journal.close()
      },
      tool: {
        // Expose core functionality as tools
        "self-improvement:reflect": {
          description: "Run reflection on recent events",
          parameters: {
            type: "object",
            properties: {
              events: { type: "array", items: { type: "object" } }
            },
            required: ["events"]
          },
          async execute({ events }) {
            return core.reflect(events)
          }
        },
        "self-improvement:route": {
          description: "Route a task to the best agent/model",
          parameters: {
            type: "object",
            properties: {
              description: { type: "string" },
              required_capabilities: { type: "array", items: { type: "string" } },
              risk_level: { type: "string", enum: ["low", "medium", "high"] },
              context_size: { type: "number" },
              budget_limit: { type: "number" },
              verification_required: { type: "boolean" }
            },
            required: ["description", "required_capabilities", "risk_level", "context_size", "budget_limit", "verification_required"]
          },
          async execute(task) {
            const registry = new core.AgentRegistry()
            core.DEFAULT_PROFILES.forEach(p => registry.register(p))
            const router = new core.ModelRouter(registry)
            return router.route(task)
          }
        },
        "self-improvement:run-evaluation": {
          description: "Run evaluation on a workflow",
          parameters: {
            type: "object",
            properties: {
              workflow_id: { type: "string" },
              cases: { type: "array", items: { type: "object" } }
            },
            required: ["workflow_id", "cases"]
          },
          async execute({ workflow_id, cases }) {
            return core.runEvaluation(workflow_id, cases)
          }
        },
        "self-improvement:create-experiment": {
          description: "Create a new experiment worktree",
          parameters: {
            type: "object",
            properties: {
              name: { type: "string" },
              description: { type: "string" }
            },
            required: ["name", "description"]
          },
          async execute({ name, description }) {
            return core.createExperiment(name, description)
          }
        }
      }
    }
  }
}

